CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "BookingStatus" AS ENUM ('PENDING_PAYMENT','CONFIRMED','CHECKED_IN','COMPLETED','PAYMENT_FAILED','EXPIRED','CANCELLED_BY_GUEST','CANCELLED_BY_OWNER');
CREATE TYPE "PaymentStatus" AS ENUM ('NOT_STARTED','ORDER_PENDING','PENDING','CAPTURED','FAILED','REFUND_PENDING','PARTIALLY_REFUNDED','REFUNDED');
CREATE TYPE "IdempotencyState" AS ENUM ('IN_PROGRESS','COMPLETED','FAILED_RETRYABLE');
CREATE TYPE "PaymentOperation" AS ENUM ('CREATE_ORDER','REQUEST_REFUND');
CREATE TYPE "WorkStatus" AS ENUM ('PENDING','IN_FLIGHT','SUCCEEDED','FAILED_RETRYABLE','DEAD');
CREATE TABLE bookings (id UUID PRIMARY KEY,"guestId" UUID NOT NULL,"ownerId" UUID NOT NULL,"propertyId" UUID NOT NULL,"roomId" UUID NOT NULL,"propertyName" VARCHAR(120) NOT NULL,"roomName" VARCHAR(120) NOT NULL,"checkIn" DATE NOT NULL,"checkOut" DATE NOT NULL,guests INTEGER NOT NULL,"capacitySnapshot" INTEGER NOT NULL,"nightlyPriceAmount" NUMERIC(12,2) NOT NULL,currency CHAR(3) NOT NULL,nights INTEGER NOT NULL,"totalAmount" NUMERIC(12,2) NOT NULL,"accommodationVersion" INTEGER NOT NULL,"roomSourceUpdatedAt" TIMESTAMPTZ(6) NOT NULL,status "BookingStatus" NOT NULL,"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'ORDER_PENDING',"paymentOrderId" UUID,"holdExpiresAt" TIMESTAMPTZ(6),version INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ("checkOut">"checkIn"),CHECK (guests>=1 AND guests<="capacitySnapshot"),CHECK ("capacitySnapshot">=1),CHECK ("nightlyPriceAmount">0 AND "totalAmount">0),CHECK (nights=("checkOut"-"checkIn")),CHECK (currency ~ '^[A-Z]{3}$'),CHECK (version>=1));
ALTER TABLE bookings ADD CONSTRAINT bookings_no_overlap EXCLUDE USING gist ("roomId" WITH =, daterange("checkIn","checkOut",'[)') WITH &&) WHERE (status IN ('PENDING_PAYMENT','CONFIRMED','CHECKED_IN'));
CREATE UNIQUE INDEX bookings_payment_order_unique ON bookings("paymentOrderId") WHERE "paymentOrderId" IS NOT NULL;
CREATE INDEX bookings_guest_created_idx ON bookings("guestId","createdAt" DESC,id DESC); CREATE INDEX bookings_owner_created_idx ON bookings("ownerId","createdAt" DESC,id DESC); CREATE INDEX bookings_owner_status_dates_idx ON bookings("ownerId",status,"checkIn",id); CREATE INDEX bookings_property_dates_idx ON bookings("propertyId","checkIn",id); CREATE INDEX bookings_hold_idx ON bookings(status,"holdExpiresAt");
CREATE TABLE booking_transitions (id UUID PRIMARY KEY,"bookingId" UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,"fromStatus" "BookingStatus","toStatus" "BookingStatus" NOT NULL,"actorType" VARCHAR(20) NOT NULL,"actorId" UUID,"reasonCode" VARCHAR(80) NOT NULL,metadata JSONB NOT NULL,"occurredAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX booking_transitions_order_idx ON booking_transitions("bookingId","occurredAt",id);
CREATE TABLE idempotency_records ("guestId" UUID NOT NULL,key VARCHAR(128) NOT NULL,"requestHash" CHAR(64) NOT NULL,"bookingId" UUID REFERENCES bookings(id) ON DELETE RESTRICT,state "IdempotencyState" NOT NULL,"responseStatus" INTEGER,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMPTZ(6) NOT NULL,PRIMARY KEY("guestId",key));
CREATE TABLE payment_work (id UUID PRIMARY KEY,"bookingId" UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,operation "PaymentOperation" NOT NULL,"idempotencyKey" VARCHAR(160) NOT NULL UNIQUE,amount NUMERIC(12,2) NOT NULL,currency CHAR(3) NOT NULL,status "WorkStatus" NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastErrorCode" VARCHAR(80),UNIQUE("bookingId",operation)); CREATE INDEX payment_work_claim_idx ON payment_work(status,"nextAttemptAt");
CREATE TABLE outbox_events (id UUID PRIMARY KEY,"aggregateId" UUID NOT NULL,"eventType" VARCHAR(120) NOT NULL,"schemaVersion" INTEGER NOT NULL DEFAULT 1,payload JSONB NOT NULL,"occurredAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"publishedAt" TIMESTAMPTZ(6),attempts INTEGER NOT NULL DEFAULT 0,"nextAttemptAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX outbox_unpublished_idx ON outbox_events("publishedAt","nextAttemptAt");
CREATE TABLE processed_events ("eventId" UUID PRIMARY KEY,"eventType" VARCHAR(120) NOT NULL,"payloadHash" CHAR(64) NOT NULL,"processedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,outcome VARCHAR(40) NOT NULL);
CREATE TABLE cancellation_decisions (id UUID PRIMARY KEY,"bookingId" UUID NOT NULL REFERENCES bookings(id) ON DELETE RESTRICT,"policyVersion" VARCHAR(80) NOT NULL,"actorType" VARCHAR(20) NOT NULL,eligible BOOLEAN NOT NULL,"refundMode" VARCHAR(20) NOT NULL,"evaluatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE INDEX cancellation_decisions_booking_idx ON cancellation_decisions("bookingId","evaluatedAt");
